/// <summary>
///  The <c>METTransferOrderExtractionBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide sales order extract business event.
/// </summary>
[BusinessEvents(classStr(METTransferOrderExtractionBusinessEventContract),
    "@MET:TransferOrderExtractionBusinessEventName",
    "@MET:TransferOrderExtractionBusinessEventDesc",
    ModuleAxapta::Inventory)]
public final class METTransferOrderExtractionBusinessEvent extends BusinessEventsBase
{
    private WMSPickingRoute wmsPickingRoute;

}

Method.Source:
    /// <summary>
    /// Constructs a new METTransferOrderExtractionBusinessEvent business event.
    /// </summary>
    /// <param name = "_wmsPickingRoute">The <c>WMSPickingRoute</c> record.</param>
    /// <returns>A new <c>METTransferOrderExtractionBusinessEvent</c> business event.</returns>
    public static METTransferOrderExtractionBusinessEvent newFromWMSPickingRoute(WMSPickingRoute _wmsPickingRoute)
    {
        METTransferOrderExtractionBusinessEvent event = new METTransferOrderExtractionBusinessEvent();
        event.parmWMSPickingRoute(_wmsPickingRoute);

        return event;
    }

/// <summary>
/// Gets and sets <c>WMSPickingRoute</c>.
/// </summary>
/// <param name = "_wmsPickingRoute">
/// <c>WMSPickingRoute</c>.
/// </param>
/// <returns>
/// <c>WMSPickingRoute</c>.
/// </returns>
private WMSPickingRoute parmWMSPickingRoute(WMSPickingRoute _wmsPickingRoute = wmsPickingRoute)
{
    wmsPickingRoute = _wmsPickingRoute;
    return wmsPickingRoute;
}

/// <summary>
/// Constructs a new METTransferOrderExtractionBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METTransferOrderExtractionBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
protected BusinessEventsContract buildContract()
{
    return METTransferOrderExtractionBusinessEventContract::newFromWMSPickingRoute(wmsPickingRoute);
}
